/**
 * Credit agent API hooks — hand-written (not generated by orval), like data-room.ts.
 * The agent investigates the borrower from public filings and drafts the CAM into the case.
 */
import { useMutation, useQuery } from "@tanstack/react-query";
import { customFetch } from "./custom-fetch";

export type AgentRunStatus = "none" | "queued" | "running" | "writing" | "done" | "failed" | "no_cam" | "cancelled";

export interface AgentStep {
  id: string;
  tool: string;
  args?: string;
  outcome: string;
}

export interface AgentRun {
  status: AgentRunStatus;
  job_id?: string;
  message?: string;
  steps?: AgentStep[];
  started_at?: string;
  finished_at?: number;
  imported?: boolean;
  imported_at?: string;
  import_error?: string;
  failed_sections?: string[];
  checks?: { decision_gate?: { decision?: string; knockouts?: string[]; cautions?: string[] }; numeric_sentences_flagged?: number; numeric_sentences_checked?: number };
  sources?: { id: string; kind: string; title?: string; url?: string }[];
  stopped_because?: string;
  stale?: boolean;
}

export const AGENT_ACTIVE: AgentRunStatus[] = ["queued", "running", "writing"];

export const getAgentRunQueryKey = (caseId: number) => ["agentRun", caseId] as const;

/** Polls every 5 s while a run is active; the server imports the CAM into the case when it finishes. */
export const useGetAgentRun = (caseId: number) =>
  useQuery({
    queryKey: getAgentRunQueryKey(caseId),
    queryFn: () => customFetch<AgentRun>(`/api/cases/${caseId}/agent`),
    enabled: !!caseId,
    refetchInterval: (q) => (AGENT_ACTIVE.includes((q.state.data?.status ?? "none") as AgentRunStatus) ? 5_000 : false),
  });

export const useStartAgentRun = () =>
  useMutation({
    mutationFn: ({ caseId }: { caseId: number }) =>
      customFetch<AgentRun>(`/api/cases/${caseId}/agent`, { method: "POST" }),
  });

export const useCancelAgentRun = () =>
  useMutation({
    mutationFn: ({ caseId }: { caseId: number }) =>
      customFetch<AgentRun>(`/api/cases/${caseId}/agent`, { method: "DELETE" }),
  });
